from pysat.formula import CNF
from pysat.solvers import Glucose3

# 19 pigeons, 18 holes
# Variables: x[i][j] means pigeon i goes to hole j
# We'll use a flat encoding: var = i*18 + j + 1

n_pigeons = 19
n_holes = 18

cnf = CNF()

# Each pigeon must be assigned to exactly one hole
for i in range(n_pigeons):
    clause = [i*18 + j + 1 for j in range(n_holes)]
    cnf.add_clause(clause)  # at least one
    # at most one: for each pair of holes, not both
    for j1 in range(n_holes):
        for j2 in range(j1+1, n_holes):
            cnf.add_clause([-(i*18 + j1 + 1), -(i*18 + j2 + 1)])

# Each hole can have at most one pigeon
for j in range(n_holes):
    for i1 in range(n_pigeons):
        for i2 in range(i1+1, n_pigeons):
            cnf.add_clause([-(i1*18 + j + 1), -(i2*18 + j + 1)])

solver = Glucose3()
solver.append_formula(cnf)
result = solver.solve()
print("Satisfiable:", result)
if result:
    model = solver.get_model()
    solution = []
    for i in range(n_pigeons):
        for j in range(n_holes):
            if model[i*18 + j] > 0:
                solution.append(j)
                break
    print("Solution:", solution)
else:
    print("UNSATISFIABLE")

